import os
import json
import re

MODELS_REGISTRY_FILE = "models.json"
PRETRAINED_MODELS_DIR = "pretrained_models"

# Hierarchical structure of available YOLO models
AVAILABLE_MODELS = {
    "YOLOv11": {
        "Detection": ["yolo11n.pt", "yolo11s.pt", "yolo11m.pt", "yolo11l.pt", "yolo11x.pt"],
        "Instance Segmentation": ["yolo11n-seg.pt", "yolo11s-seg.pt", "yolo11m-seg.pt", "yolo11l-seg.pt", "yolo11x-seg.pt"],
        "Pose/Keypoints": ["yolo11n-pose.pt", "yolo11s-pose.pt", "yolo11m-pose.pt", "yolo11l-pose.pt", "yolo11x-pose.pt"],
        "Oriented Detection": ["yolo11n-obb.pt", "yolo11s-obb.pt", "yolo11m-obb.pt", "yolo11l-obb.pt", "yolo11x-obb.pt"],
        "Classification": ["yolo11n-cls.pt", "yolo11s-cls.pt", "yolo11m-cls.pt", "yolo11l-cls.pt", "yolo11x-cls.pt"],
    },
    "YOLOv8": {
        "Detection": ["yolov8n.pt", "yolov8s.pt", "yolov8m.pt", "yolov8l.pt", "yolov8x.pt"],
        "Instance Segmentation": ["yolov8n-seg.pt", "yolov8s-seg.pt", "yolov8m-seg.pt", "yolov8l-seg.pt", "yolov8x-seg.pt"],
    },
    "YOLOv5": {
        "Detection": ["yolov5n.pt", "yolov5s.pt", "yolov5m.pt", "yolov5l.pt", "yolov5x.pt"],
    }
}


class ModelManager:
    def __init__(self):
        self.registry_path = MODELS_REGISTRY_FILE
        self.models = self.load_registry()

    def _generate_friendly_name(self, version, task, model_file):
        """Generates a descriptive name like 'YOLOv11-n (Detection)'."""
        match = re.match(r"yolo(v\d+|\d+)(n|s|m|l|x|c|e)", model_file)
        size = match.group(2) if match else '?'
        base_name = f"{version}-{size}"
        if "YOLOv8-Nano" in AVAILABLE_MODELS.get(version, {}).get(task, []) and "yolov8n.pt" == model_file:
             base_name += " (Default)"
        return f"{base_name} ({task})"


    def initialize_registry(self):
        """Creates a new registry from the hierarchical model structure."""
        print("Initializing new model registry...")
        registry = {}
        for version, tasks in AVAILABLE_MODELS.items():
            for task, model_files in tasks.items():
                for model_file in model_files:
                    friendly_name = self._generate_friendly_name(version, task, model_file)
                    registry[model_file] = {"name": friendly_name, "path": model_file, "version": version, "task": task}
        return registry

    def load_registry(self):
        """Loads the model registry, creating it if it doesn't exist."""
        if os.path.exists(self.registry_path):
            with open(self.registry_path, "r") as f:
                return json.load(f)
        else:
            new_registry = self.initialize_registry()
            self.save_registry(new_registry)
            return new_registry

    def save_registry(self, registry_data=None):
        """Saves the current model registry to disk."""
        data_to_save = registry_data if registry_data is not None else self.models
        with open(self.registry_path, "w") as f:
            json.dump(data_to_save, f, indent=4)

    def get_model_names(self):
        """Returns a list of friendly names for all registered models."""
        return [details["name"] for details in self.models.values()]

    def get_model_path(self, friendly_name):
        """Finds the path of a model from its friendly name."""
        for key, details in self.models.items():
            if details["name"] == friendly_name:
                model_path = details["path"]
                if not os.path.isabs(model_path):
                    return os.path.join(PRETRAINED_MODELS_DIR, model_path)
                return model_path
        return None

    def get_model_versions(self):
        """Returns a list of available model versions."""
        return list(AVAILABLE_MODELS.keys())

    def get_tasks_for_version(self, version):
        """Returns a list of tasks for a given model version."""
        return list(AVAILABLE_MODELS.get(version, {}).keys())

    def get_model_names_for_task(self, version, task):
        """Returns friendly names for a given version and task."""
        names = []
        model_files = AVAILABLE_MODELS.get(version, {}).get(task, [])
        for model_file in model_files:
            # Find the corresponding friendly name in the full registry
            if model_file in self.models:
                names.append(self.models[model_file]["name"])
        return names

    def register_model(self, path_to_model, name=None):
        """Adds a new custom model to the registry."""
        if not os.path.exists(path_to_model):
            print(f"Warning: Model path does not exist: {path_to_model}")
            return

        key = os.path.abspath(path_to_model)
        if key in self.models:
            print(f"Model at path {key} is already registered.")
            return

        if name is None:
            name = f"Custom Model ({os.path.basename(path_to_model)})"

        self.models[key] = {"name": name, "path": key, "version": "Custom", "task": "Custom"}
        self.save_registry()
        print(f"Registered new model: {name}")

